// Keep only new signals of the kinds we care about. Static data persists between production runs.
const KINDS = new Set(['smart_buy', 'kol_buy', 'ath', 'cto', 'bundler_sell']);
const store = $getWorkflowStaticData('global');
const seen = new Set(store.seen || []);
const rows = ($input.first().json.data || []).filter((s) => KINDS.has(s.kind));
const fresh = [];
for (const s of rows) {
  const id = `${s.kind}:${s.tokenKey}:${s.at}`;
  if (seen.has(id)) continue;
  seen.add(id);
  fresh.push(s);
}
store.seen = [...seen].slice(-2000);
const partial = $input.first().json.partial;
return fresh.slice(-10).map((s) => ({ json: {
  content: `${s.label}: $${s.symbol ?? '?'} ${s.detail ?? ''}\nhttps://useclaudia.xyz/t/sol/${String(s.tokenKey).replace('sol:', '')}${partial ? `\n(data partial: ${partial})` : ''}\nResearch alert, not financial advice.`,
} }));
